<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$base=defined('BASE_PATH')?BASE_PATH:''; ?>
<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demandas de repasse</title><main><nav><a href="<?= $e($base) ?>/admin/repasses/demandas">Demandas</a> · <a href="<?= $e($base) ?>/admin/saques">Repasses</a></nav><h1>Analisar demandas de repasse</h1><p>Solicitante e aprovador devem ser pessoas distintas. Quando exigido, a segunda aprovacao precisa de outro responsavel.</p><p>A decisao nao e comprovante de pagamento.</p>
<?php if(!$r['cases']): ?><p>Nenhuma demanda disponivel.</p><?php endif ?>
<?php foreach($r['cases'] as $d): ?><article data-demanda-id="<?= $e($d['id']) ?>"><h2>Demanda <?= $e($d['id']) ?></h2><p>Job <?= $e($d['job_id']) ?> · R$ <?= $e($d['amount']) ?> · <?= $e($d['status']) ?></p><p><?= $d['requires_dual']?'Dupla aprovacao obrigatoria':'Uma aprovacao de outro responsavel' ?></p><p><?= $e($d['reason']) ?></p>
<?php if($d['first_manager']!==null): ?><p>Primeira decisao: <?= $e($d['first_manager']) ?> · <?= $e($d['first_at']) ?> · <?= $e($d['first_note']) ?></p><?php endif ?>
<?php if($d['second_manager']!==null): ?><p>Segunda decisao: <?= $e($d['second_manager']) ?> · <?= $e($d['second_at']) ?> · <?= $e($d['second_note']) ?></p><?php endif ?>
<?php if($single && in_array($d['status'],['pendente','aprovada_parcial'],true) && (int)$user['id']!==$d['requester_id'] && (int)$user['id']!==$d['first_manager']): ?>
<form action="<?= $e($base) ?>/admin/repasses/demanda/decidir" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="request_key" value="<?= $e($key) ?>"><input type="hidden" name="revision" value="<?= $e($d['revision']) ?>"><input type="hidden" name="demanda_id" value="<?= $e($d['id']) ?>"><label for="nota">Nota da decisao</label><textarea id="nota" name="nota" maxlength="500" required></textarea><button name="veredito" value="aprovar">Aprovar</button><button name="veredito" value="rejeitar">Rejeitar</button></form>
<?php elseif(!$single): ?><a href="<?= $e($base) ?>/admin/repasses/demanda?demanda_id=<?= $e($d['id']) ?>">Consultar e decidir</a><?php endif ?>
<?php if($d['status']==='aprovada' && $user['tipo']==='admin'): ?><p><a href="<?= $e($base) ?>/admin/repasses/recuperacao?demanda_id=<?= $e($d['id']) ?>">Conferir recuperacao</a></p><?php endif ?></article><?php endforeach ?></main></html>
